SELECT r.request_id,r.created_at,r.status AS request_status,f.name AS facility_name,p.payment_id,p.payment_status,(SELECT count(*) FROM public."SSP_Facility_Booking" b WHERE b.payment=r.payment) AS confirmed_bookings FROM public."SSP_Facility_Booking_Request" r LEFT JOIN public."SSP_Facility" f ON f.id=r.facility LEFT JOIN public."SSP_Payment" p ON p.pay_rec_id=r.payment WHERE r.requested_by='3096f2ea-dba7-46fa-9b56-00add869b034' ORDER BY r.created_at DESC NULLS LAST LIMIT 3;
